using System;using System.Linq;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;
namespace IdleIntelligence.Runtime {
 // Shared training/research presentation. Quotes are cached; live work and affordability update independently.
 public sealed class LearningCard:MonoBehaviour {
  public ActionCard Card;public Text Effect,Credits,Data,Duration,Requirement,ActionLabel;public Image CreditIcon,DataIcon,Progress;public Button StartAction,Details;
  Image actionSurface;GameRuntime game;string kind,id,language;int index,level=-1,quality=-1,efficiency=-1,integration=-1;ScientificNumber cost=ScientificNumber.Zero,dataCost=ScientificNumber.Zero;float nextQuote;bool initialized;RectTransform viewport;bool allowed;string quotedBlock;bool queueAllowed;long revision=-1;
  public void Initialize(GameRuntime runtime,string selected,int i){game=runtime;actionSurface=StartAction.GetComponent<Image>();viewport=game.Content.GetComponentInParent<ScrollRect>().viewport;kind=selected;index=i;id=kind=="training"?PrestigeAutomation.Tracks[i]:Balance.Research[i].Id;StartAction.onClick.AddListener(()=>Card.Button.onClick.Invoke());Details.name="Details-"+kind+"-"+id;Details.onClick.AddListener(()=>game.ShowDetails(kind,index));var shell=game.GetComponent<MobileShell>();CreditIcon.sprite=game.Credits.transform.parent.Find("ResourceIcon")?.GetComponent<Image>()?.sprite??shell.ResourceIcons[0];DataIcon.sprite=game.Data.transform.parent.Find("ResourceIcon")?.GetComponent<Image>()?.sprite??shell.ResourceIcons[1];int area=kind=="training"?(i==0?2:i==1?1:3):Workshop.ResearchArea(id);Card.Icon.sprite=area==0?DataIcon.sprite:area==1?game.HardwareSprites[1]:area==2?game.ModelPrefab.ModelArt:area==3?game.WorkshopPrefab.ComponentSprites[0]:game.ResearchTab.transform.Find("NavigationIcon").GetComponent<Image>().sprite;RefreshView();}
  string Name(string track)=>track=="integration"?"Integration":SettingsRules.Text(game.State.Settings.language,"workshop:"+track);
  string N(ScientificNumber n)=>NumberFormatting.Format(n,game.State.Settings.numberFormat);
  string Human(string block){if(block==null)return "";foreach(var r in Balance.Research)block=block.Replace(r.Id,SettingsRules.Text(game.State.Settings.language,"research:"+r.Id));return UiLocalizedText.Translate(block,game.State.Settings.language);}
  public void RefreshView(){var s=game.State;if(initialized&&language==s.Settings.language&&revision==game.PresentationRevision){var rect=(RectTransform)transform;float top=viewport.InverseTransformPoint(rect.TransformPoint(new Vector3(0,rect.rect.yMax,0))).y,bottom=viewport.InverseTransformPoint(rect.TransformPoint(new Vector3(0,rect.rect.yMin,0))).y;if(top<viewport.rect.yMin||bottom>viewport.rect.yMax)return;}initialized=true;bool training=kind=="training",de=s.Settings.language=="de";int current=training?Game.TrainingLevel(s,id):s.Research[index];bool quote=Time.unscaledTime>=nextQuote||level!=current||quality!=s.Quality||efficiency!=s.Efficiency||integration!=s.Workshop.integration||language!=s.Settings.language||revision!=game.PresentationRevision;
   if(quote){nextQuote=Time.unscaledTime+1;level=current;quality=s.Quality;efficiency=s.Efficiency;integration=s.Workshop.integration;language=s.Settings.language;revision=game.PresentationRevision;Card.Title.text=(training?Name(id):SettingsRules.Text(language,"research:"+id))+" · Lv. "+level;cost=training?Game.TrainingCost(s,id):ScientificNumber.Zero;dataCost=training?Game.TrainingData(s,id):Game.ResearchCost(s,index);Credits.text=N(cost);Data.text=N(dataCost);CreditIcon.transform.parent.gameObject.SetActive(training);DataIcon.transform.parent.gameObject.SetActive(!training||!dataCost.IsZero);Details.GetComponentInChildren<Text>().text="i";double work=training?Game.TrainingWork(s,id):Game.ResearchWork(s,index),speed=training?(id=="quality"&&Game.IntroQuality(s)?1:Game.WorkSpeed(s)):(id=="dataGeneration"&&Game.IntroResearch(s)?1:Game.ResearchSpeed(s));Duration.text=Math.Ceiling(work/speed)+" s";
    if(training){var next=s.Copy();if(id=="quality")next.Quality++;else if(id=="efficiency")next.Efficiency++;else next.Workshop.integration++;var income=Game.Income(s);var after=Game.Income(next);Effect.text=(de?"Einnahmen ":"Income ")+N(income)+" → "+N(after)+" /s";if(id=="efficiency")Effect.text=(de?"Nutzer ":"Users ")+N(Game.Users(s))+" → "+N(Game.Users(next));if(id=="integration")Effect.text=(de?"Item-Boni ×":"Item bonuses ×")+Math.Pow(PrestigeRules.Has(s,"T10")?PrestigeRules.V("integrationPerfect"):ItemBalance.IntegrationBase,level).ToString("F3")+" → ×"+Math.Pow(PrestigeRules.Has(s,"T10")?PrestigeRules.V("integrationPerfect"):ItemBalance.IntegrationBase,level+1).ToString("F3");allowed=Game.TrainingAvailable(s,id);Requirement.text=allowed?"":id=="integration"&&!PrestigeRules.Has(s,"T04")?(de?"INT: Integration freischalten":"Unlock Integration in INT"):id=="integration"&&level>=MetaRules.IntegrationLimit(s)?(de?"Maximales Level":"Maximum level"):(de?"In dieser Challenge gesperrt":"Locked in this challenge");}
    else{quotedBlock=Game.ResearchBlock(s,index);if(quotedBlock=="Zu wenig Daten")quotedBlock=null;queueAllowed=quotedBlock=="Labor belegt"&&PrestigeAutomation.CanQueueResearch(s,id);string text=SettingsRules.Text(language,(Balance.Research[index].Project?"project-effect:":"research-effect:")+id);Effect.text=text.Length>125?text.Substring(0,122)+"…":text;if(!Balance.Research[index].Project){var after=s.Copy();after.Research[index]++;Func<GameState,ScientificNumber> metric=id=="dataGeneration"||id=="syntheticData"||id=="dataFlywheel"?Game.DataRate:id=="computeOptimization"||id=="hardwareIntegration"||id=="parallelArchitecture"||id=="hardwareCoDesign"||id=="distributedInference"?Game.Compute:(Func<GameState,ScientificNumber>)null;if(metric!=null)Effect.text=N(metric(s))+" → "+N(metric(after))+((id=="dataGeneration"||id=="syntheticData"||id=="dataFlywheel")?(de?" Daten/s":" Data/s"):" Compute")+"\n"+(text.Length>70?text.Substring(0,67)+"…":text);}}
   }
   Credits.color=s.Credits.CompareTo(cost)>=0?GameTheme.Enough:GameTheme.Missing;Data.color=s.Data.CompareTo(dataCost)>=0?GameTheme.Enough:GameTheme.Missing;Job job=training?(s.Training?.id==id?s.Training:null):PrestigeAutomation.ResearchJobs(s).FirstOrDefault(j=>j.id==id);bool queued=training?s.Prestige.trainingQueue.Any(q=>q.track==id):s.Prestige.researchQueue.Contains(id);bool can;
   if(training){bool queue=s.Training!=null&&PrestigeRules.Has(s,"T03")&&s.Prestige.trainingQueue.Length<2;can=allowed&&(s.Training==null?s.Credits.CompareTo(cost)>=0&&s.Data.CompareTo(dataCost)>=0:queue);ActionLabel.text=s.Training!=null&&queue?(de?"Einreihen":"Queue"):(de?"Trainieren":"Train");}
   else{string block=quotedBlock;if(block==null&&s.Data.CompareTo(dataCost)<0)block="Zu wenig Daten";can=block==null||block=="Labor belegt"&&queueAllowed;Requirement.text=job!=null?"":queued?(de?"In Warteschlange":"Queued"):Human(block);ActionLabel.text=block=="Labor belegt"?(de?"Einreihen":"Queue"):(de?"Forschen":"Research");}
   if(job!=null){double speed=training?Game.WorkSpeed(s):Game.ResearchSpeed(s,job);if(job.intro)speed=1;Duration.text=Math.Ceiling(Math.Max(0,(job.required-job.done)/speed))+" s";Requirement.text=de?"Training läuft":"Training in progress";if(!training)Requirement.text=de?"Labor arbeitet":"Research in progress";ActionLabel.text=de?"Läuft":"Running";}CreditIcon.transform.parent.gameObject.SetActive(job==null&&training);DataIcon.transform.parent.gameObject.SetActive(job==null&&(!training||!dataCost.IsZero));Requirement.gameObject.SetActive(Requirement.text.Length>0);StartAction.transform.parent.gameObject.SetActive(job==null);GetComponent<LayoutElement>().minHeight=GetComponent<LayoutElement>().preferredHeight=job!=null?176:Requirement.text.Length>0?214:188;Progress.gameObject.SetActive(job!=null);Progress.fillAmount=job==null?0:(float)Math.Min(1,job.done/job.required);Card.Button.interactable=StartAction.interactable=game.Writable&&can;actionSurface.sprite=StartAction.interactable?GameTheme.GoldButton:GameTheme.Steel;ActionLabel.color=StartAction.interactable?GameTheme.Background:GameTheme.Muted;}
 }
}
